<template>
  <main class="admin-page">
    <aside class="sidebar">
      <router-link to="/admin" class="brand"><i>🌿</i><span>Nhà Vườn <em>Admin</em><small>QUẢN LÝ VƯỜN ƯƠM</small></span></router-link>
      <nav><button v-for="item in menu" :key="item.id" :class="{active: page === item.id}" @click="page = item.id"><span>{{ item.icon }}</span>{{ item.label }}<b v-if="item.id === 'orders' && pendingOrders">{{ pendingOrders }}</b></button></nav>
      <div class="account"><span class="avatar">{{ initials }}</span><div><b>{{ user?.fullname || 'Nhân viên A' }}</b><small>Chủ vườn</small></div><button @click="logout" title="Đăng xuất">↗</button></div>
    </aside>
    <section class="workspace">
      <header class="topbar"><span><b>Quyền: CHỦ VƯỜN (ADMIN)</b> · Xin chào, {{ user?.fullname || 'Nhân viên A' }}!</span><button @click="note('Đang mở thông tin tài khoản.')">🌱 Tài khoản</button></header>
      <section v-if="page === 'overview'" class="content">
        <Title eyebrow="Trung tâm điều hành" title="Tổng quan vườn ươm" subtitle="Theo dõi hoạt động vườn ươm trong hôm nay." action="＋ Thêm lô cây" @action="openNewLot" />
        <button class="warning" @click="page = 'lots'">⚠ <b>Lô Cam Sành (Khu A)</b> đã đạt 62 ngày tuổi — vượt ngưỡng xuất vườn 60 ngày. <span>Xử lý →</span></button>
        <div class="metrics"><Metric label="Số cây đang ươm" :value="growingTotal + ' cây'" note="Đang được chăm sóc" /><Metric class="green" label="Cây sẵn sàng bán" :value="readyTotal + ' cây'" note="Có thể tạo đơn ngay" /><Metric class="amber" label="Đơn hàng chờ duyệt" :value="pendingOrders + ' đơn'" note="Cần phản hồi hôm nay" /></div>
        <section class="panel"><PanelHead title="Nhật ký lô ươm cần theo dõi" action="Xem toàn bộ →" @action="page = 'lots'"/><LotTable :items="lots.slice(0,4)" @status="cycle" @edit="editLot"/></section>
      </section>
      <section v-else-if="page === 'lots'" class="content">
        <Title eyebrow="Quản lý cây giống" title="Lô cây ươm" subtitle="Theo dõi số lượng, tuổi cây và tình trạng từng lô." action="＋ Thêm lô cây" @action="openNewLot" />
        <section class="panel"><div class="toolbar"><label>⌕ <input v-model="search" placeholder="Tìm tên cây hoặc mã lô"/></label><div><button v-for="f in filters" :key="f" :class="{selected: filter === f}" @click="filter=f">{{ f }}</button></div></div><LotTable :items="visibleLots" @status="cycle" @edit="editLot"/><p v-if="!visibleLots.length" class="empty">Không tìm thấy lô cây phù hợp.</p></section>
      </section>
      <section v-else-if="page === 'care'" class="content">
        <Title eyebrow="Vận hành vườn" title="Hao hụt & chăm sóc" subtitle="Lịch công việc mẫu theo từng khu vực." action="＋ Tạo lịch chăm sóc" @action="addCare" />
        <div class="task-list"><article v-for="task in tasks" :key="task.id" class="task"><i>{{ task.icon }}</i><div><small>{{ task.area }} · {{ task.time }}</small><h3>{{ task.title }}</h3><p>{{ task.detail }}</p></div><button :class="{done:task.done}" @click="task.done=!task.done">{{ task.done ? 'Đã hoàn tất' : 'Hoàn tất' }}</button></article></div>
      </section>
      <section v-else-if="page === 'orders'" class="content">
        <Title eyebrow="Kinh doanh" title="Đơn hàng" subtitle="Duyệt hoặc từ chối đơn mua cây giống." />
        <section class="panel"><PanelHead title="Đơn hàng gần đây" :action="pendingOrders + ' đơn chờ duyệt'"/><article v-for="order in orders" :key="order.code" class="order"><div><b>{{ order.code }}</b><strong>{{ order.customer }}</strong><small>{{ order.product }} · {{ order.quantity }} cây</small></div><span :class="['status', statusClass(order.status)]">{{ order.status }}</span><b class="price">{{ order.total }}</b><div v-if="order.status==='Chờ duyệt'"><button class="approve" @click="decide(order,true)">Duyệt</button><button class="reject" @click="decide(order,false)">Từ chối</button></div><button v-else class="text-button" @click="note(`Đơn ${order.code}: ${order.status}`)">Chi tiết</button></article></section>
      </section>
      <section v-else-if="page === 'pricing'" class="content">
        <Title eyebrow="Kinh doanh" title="Sửa biểu giá" subtitle="Điều chỉnh giá bán mẫu theo từng loại cây." action="Lưu biểu giá" @action="note('Đã lưu biểu giá mới.')" />
        <section class="panel price-grid"><label v-for="item in prices" :key="item.name"><i>{{item.icon}}</i><span><b>{{item.name}}</b><small>Giá bán / cây</small></span><input v-model.number="item.value" type="number" min="0"/><em>đ</em></label></section>
      </section>
      <section v-else-if="page === 'staff'" class="content">
        <Title eyebrow="Vận hành vườn" title="Nhân sự" subtitle="Danh sách nhân sự và ca làm việc mẫu." action="＋ Thêm nhân sự" @action="addStaff" />
        <div class="staff-grid"><article v-for="person in staff" :key="person.name" class="staff"><i class="avatar">{{person.initial}}</i><div><h3>{{person.name}}</h3><small>{{person.role}}</small><p>Ca hôm nay: <b>{{person.shift}}</b></p></div><button @click="note(`Đã gửi nhắc việc cho ${person.name}.`)">Nhắc việc</button></article></div>
      </section>
      <section v-else class="content">
        <Title eyebrow="Báo cáo tài chính" title="Doanh thu" subtitle="Kết quả kinh doanh mẫu trong tháng 09/2026." action="⇩ Xuất báo cáo" @action="note('Đã tải báo cáo doanh thu mẫu.')" />
        <div class="metrics"><Metric class="green" label="Doanh thu tháng này" value="48.650.000đ" note="↑ 12,6% so với tháng trước"/><Metric label="Đơn đã hoàn thành" value="36 đơn" note="Giá trị đơn trung bình 1.351.000đ"/><Metric class="amber" label="Chi phí vận hành" value="15.240.000đ" note="Phân bón, vật tư và nhân công"/></div>
        <section class="panel chart-panel"><PanelHead title="Doanh thu theo tuần" action="Đơn vị: triệu đồng"/><div class="chart"><div v-for="week in revenue" :key="week.name"><b>{{week.amount}}</b><i :style="{height:week.value+'%'}"></i><span>{{week.name}}</span></div></div></section>
      </section>
    </section>
    <div v-if="showForm" class="overlay" @click.self="showForm=false"><form class="modal" @submit.prevent="saveLot"><button type="button" class="close" @click="showForm=false">×</button><p class="eyebrow">{{ editing ? 'Cập nhật lô cây' : 'Tạo lô mới' }}</p><h2>{{ editing ? 'Chỉnh sửa thông tin lô' : 'Thêm lô cây giống' }}</h2><label>Tên cây<input v-model.trim="form.name" required/></label><div class="form-row"><label>Mã lô<input v-model.trim="form.code" required/></label><label>Khu vực<select v-model="form.area"><option>Khu A</option><option>Khu B</option><option>Khu C</option></select></label></div><div class="form-row"><label>Số lượng<input v-model.number="form.quantity" type="number" min="1" required/></label><label>Ngày ươm<input v-model="form.date" type="date" required/></label></div><button class="primary">{{editing?'Lưu thay đổi':'Tạo lô cây'}}</button></form></div>
    <p v-if="message" class="toast">✓ {{message}}</p>
  </main>
</template>

<script setup lang="ts">
import { computed, defineComponent, h, onMounted, ref } from 'vue'
import { useRouter } from 'vue-router'
type Lot = { code:string; name:string; date:string; age:number; area:string; quantity:number; status:string }
const statusClass=(value:string)=>value==='Sẵn sàng bán'?'ready':value==='Đang ươm'?'growing':'attention'
const Title=defineComponent({props:{eyebrow:String,title:String,subtitle:String,action:String},emits:['action'],setup(p,{emit}){return()=>h('div',{class:'title'},[h('div',[h('p',{class:'eyebrow'},p.eyebrow),h('h1',p.title),h('span',p.subtitle)]),p.action?h('button',{class:'primary',onClick:()=>emit('action')},p.action):null])}})
const Metric=defineComponent({props:{label:String,value:String,note:String},setup(p){return()=>h('article',{class:'metric'},[h('small',p.label),h('strong',p.value),h('span',p.note)])}})
const PanelHead=defineComponent({props:{title:String,action:String},emits:['action'],setup(p,{emit}){return()=>h('div',{class:'panel-head'},[h('h2',p.title),p.action?h('button',{class:'text-button',onClick:()=>emit('action')},p.action):null])}})
const LotTable=defineComponent({
  props:{items:{type:Array as()=>Lot[],required:true}}, emits:['status','edit'],
  setup(p,{emit}) { return () => h('div',{class:'table-wrap'},[
    h('table',[
      h('thead',[h('tr',['Mã lô','Loại cây','Ngày ươm','Tuổi cây','Vị trí','Số lượng còn lại','Trạng thái',''].map(x=>h('th',x)))]),
      h('tbody',p.items.map(l=>h('tr',{key:l.code},[
        h('td',l.code), h('td',h('b',l.name)), h('td',l.date), h('td',l.age+' ngày'), h('td',l.area),
        h('td',new Intl.NumberFormat('vi-VN').format(l.quantity)+' cây'),
        h('td',h('span',{class:['status',statusClass(l.status)]},l.status)),
        h('td',[h('button',{class:'table-button',onClick:()=>emit('status',l)},'Đổi trạng thái'),h('button',{class:'edit',onClick:()=>emit('edit',l)},'Sửa')])
      ])))
    ])
  ]) }
})
const router=useRouter(), user=ref<{fullname?:string}|null>(null),page=ref('overview'),search=ref(''),filter=ref('Tất cả'),showForm=ref(false),editing=ref(''),message=ref('')
const menu=[{id:'overview',label:'Tổng quan',icon:'▦'},{id:'lots',label:'Lô cây ươm',icon:'⚑'},{id:'care',label:'Hao hụt & chăm sóc',icon:'✉'},{id:'orders',label:'Đơn hàng',icon:'◆'},{id:'pricing',label:'Sửa biểu giá',icon:'♨'},{id:'staff',label:'Nhân sự',icon:'♟'},{id:'revenue',label:'Doanh thu',icon:'▰'}]
const lots=ref<Lot[]>([{code:'LO-01',name:'Cam Sành Giống (F1)',date:'01/05/2026',age:62,area:'Khu A',quantity:500,status:'Sẵn sàng bán'},{code:'LO-02',name:'Mít Changai',date:'20/05/2026',age:43,area:'Khu B',quantity:785,status:'Đang ươm'},{code:'LO-03',name:'Xoài Đài Loan',date:'16/05/2026',age:50,area:'Khu A',quantity:400,status:'Sẵn sàng bán'},{code:'LO-04',name:'Khế Ngọt',date:'15/06/2026',age:20,area:'Khu B',quantity:600,status:'Đang ươm'},{code:'LO-05',name:'Bưởi da xanh',date:'01/07/2026',age:34,area:'Khu C',quantity:320,status:'Cần kiểm tra'}])
const filters=['Tất cả','Sẵn sàng bán','Đang ươm','Cần kiểm tra'];const visibleLots=computed(()=>lots.value.filter(l=>(filter.value==='Tất cả'||l.status===filter.value)&&`${l.name} ${l.code}`.toLowerCase().includes(search.value.toLowerCase())));const readyTotal=computed(()=>lots.value.filter(l=>l.status==='Sẵn sàng bán').reduce((n,l)=>n+l.quantity,0));const growingTotal=computed(()=>lots.value.filter(l=>l.status==='Đang ươm').reduce((n,l)=>n+l.quantity,0))
const tasks=ref([{id:1,icon:'💧',area:'Khu A',time:'08:00',title:'Tưới nước đợt sáng',detail:'Cam Sành, Xoài Đài Loan',done:false},{id:2,icon:'🌿',area:'Khu B',time:'10:30',title:'Bón phân hữu cơ',detail:'Mít Changai và Khế Ngọt',done:false},{id:3,icon:'🔎',area:'Khu C',time:'15:00',title:'Kiểm tra sâu bệnh',detail:'Kiểm tra lá Bưởi da xanh',done:true}])
const orders=ref([{code:'#DH-2409',customer:'Nguyễn Minh Anh',product:'Cam Sành F1',quantity:120,total:'4.800.000đ',status:'Chờ duyệt'},{code:'#DH-2408',customer:'Trang trại An Phú',product:'Mít Changai',quantity:80,total:'3.600.000đ',status:'Đã duyệt'},{code:'#DH-2407',customer:'Lê Văn Bình',product:'Xoài Đài Loan',quantity:60,total:'2.700.000đ',status:'Đang giao'}]);const pendingOrders=computed(()=>orders.value.filter(x=>x.status==='Chờ duyệt').length)
const prices=ref([{name:'Cam Sành F1',icon:'🍊',value:40000},{name:'Mít Changai',icon:'🌳',value:45000},{name:'Xoài Đài Loan',icon:'🥭',value:42000},{name:'Bưởi da xanh',icon:'🍐',value:50000}]);const staff=ref([{name:'Trần Minh Khoa',initial:'TK',role:'Kỹ thuật viên',shift:'07:00 – 16:00'},{name:'Nguyễn Thị Lan',initial:'NL',role:'Nhân viên chăm sóc',shift:'08:00 – 17:00'},{name:'Phạm Quốc Huy',initial:'PH',role:'Nhân viên kho',shift:'07:30 – 16:30'}]);const revenue=[{name:'Tuần 1',value:53,amount:'9,8'},{name:'Tuần 2',value:70,amount:'12,6'},{name:'Tuần 3',value:45,amount:'8,1'},{name:'Tuần 4',value:100,amount:'18,2'}]
const form=ref({name:'',code:'',area:'Khu A',quantity:100,date:'2026-09-08'});const initials=computed(()=>((user.value?.fullname||'NV').split(' ').map(x=>x[0]).slice(-2).join('')).toUpperCase())
function note(text:string){message.value=text;setTimeout(()=>message.value='',2500)}function cycle(l:Lot){l.status=l.status==='Đang ươm'?'Sẵn sàng bán':l.status==='Sẵn sàng bán'?'Cần kiểm tra':'Đang ươm';note(`Đã cập nhật trạng thái ${l.code}.`)}function decide(o:typeof orders.value[number],yes:boolean){o.status=yes?'Đã duyệt':'Đã từ chối';note(`${yes?'Đã duyệt':'Đã từ chối'} đơn ${o.code}.`)}function addCare(){tasks.value.unshift({id:Date.now(),icon:'🪴',area:'Khu A',time:'16:00',title:'Lịch chăm sóc mới',detail:'Cần phân công nhân sự',done:false});note('Đã tạo lịch chăm sóc mẫu.')}function addStaff(){staff.value.push({name:'Nhân sự mới',initial:'MS',role:'Nhân viên vườn ươm',shift:'Chưa phân ca'});note('Đã thêm nhân sự mẫu.')}function openNewLot(){editing.value='';form.value={name:'',code:`LO-${String(lots.value.length+1).padStart(2,'0')}`,area:'Khu A',quantity:100,date:'2026-09-08'};showForm.value=true}function editLot(l:Lot){editing.value=l.code;form.value={name:l.name,code:l.code,area:l.area,quantity:l.quantity,date:'2026-09-08'};showForm.value=true}function saveLot(){const saved:Lot={...form.value,date:new Date(form.value.date).toLocaleDateString('vi-VN'),age:0,status:'Đang ươm'};const i=lots.value.findIndex(l=>l.code===editing.value);if(i<0)lots.value.unshift(saved);else lots.value[i]={...lots.value[i],...saved};showForm.value=false;note(i<0?'Đã tạo lô cây mới.':'Đã lưu thay đổi lô cây.')}function logout(){localStorage.removeItem('currentUser');router.push('/login')}onMounted(()=>{const data=localStorage.getItem('currentUser');if(data)user.value=JSON.parse(data)})
</script>

<style scoped>
